const staticData = $getWorkflowStaticData('global');

staticData.titel = 'Einkauf | überfällige Lieferantenbestellungen vom '+ $now.setZone('Europe/Berlin').toFormat('yyyy-MM-dd');
staticData.sendtoSammel = 'einkauf@buecherbuechse.de, christoph@buecherbuechse.de, lisa@buecherbuechse.de';
staticData.mailDomain = 'buecherbuechse.de';

return [
  {
    json: {
      success: true,
    },
  },
];

