return items.map(item => {
  const row = item.json;

  const pmName = String(row.Produktmanager ?? '').trim();
  const pmMail = String(row.MailProduktmanager ?? '').trim();

  // Lieferdatum lesbar machen (YYYY-MM-DD)
  const lieferdatum = String(row.Lieferdatum ?? '').slice(0, 10);

  return {
