// Sammelmail an Einkauf & GF: ALLE Positionen, sortiert nach Überfälligkeit.
const staticData = $getWorkflowStaticData('global');
const titel = staticData.titel || 'Überfällige Lieferantenbestellungen';
const sendto = staticData.sendtoSammel || '';

const escapeHtml = (value) => {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
};

const sortiert = items
  .map(i => i.json)
  .sort((a, b) => Number(b.TageUeberfaellig) - Number(a.TageUeberfaellig));

const zeilen = sortiert.map(row => `
    <tr>
      <td>${escapeHtml(row.Bestellnummer)}</td>
      <td>${escapeHtml(row.Lieferant)}</td>
      <td>${escapeHtml(row.ArtNr)}</td>
      <td>${escapeHtml(row.Artikel)}</td>
      <td align="right">${escapeHtml(row.MengeOffen)}</td>
      <td>${escapeHtml(row.Lieferdatum)}</td>
      <td align="right">${escapeHtml(row.TageUeberfaellig)}</td>
      <td>${escapeHtml(row.Besteller)}</td>
      <td>${escapeHtml(row.Produktmanager)}</td>
    </tr>`).join('');

const mailText = `
<p>Der ${escapeHtml(titel)} - Flow hat folgende überfällige, offene Lieferantenbestellungen (in Bearbeitung) gefunden:</p>

<p>Insgesamt ${escapeHtml(sortiert.length)} Positionen, sortiert nach Überfälligkeit.</p>

<table border="1" cellpadding="6" cellspacing="0" style="border-collapse: collapse; font-family: Arial, sans-serif; font-size: 14px;">
  <thead>
    <tr>
      <th align="left">Bestellnr.</th>
      <th align="left">Lieferant</th>
      <th align="left">ArtNr</th>
      <th align="left">Artikel</th>
      <th align="right">Menge offen</th>
      <th align="left">Lieferdatum</th>
      <th align="right">Tage überfällig</th>
      <th align="left">Besteller</th>
      <th align="left">Produktmanager</th>
    </tr>
  </thead>
  <tbody>${zeilen}
  </tbody>
</table>

<p>Liebe Grüße<br>${escapeHtml(titel)} - Flow</p>
`;

return [
  {
    json: {
      titel,
      sendto,
      anzahlPositionen: sortiert.length,
      mailText,
    },
  },
];

// Empfänger-Gruppierung: ein Item pro Empfänger-Mailadresse (PM ODER Besteller).
// Jede Position wird der/den betroffenen Person(en) zugeordnet (PM und/oder Besteller).
// Ist Besteller == PM, erhält die Person die Position nur einmal -> keine Doppel-Mails.
const staticData = $getWorkflowStaticData('global');
const titel = staticData.titel || 'Überfällige Lieferantenbestellungen';

const escapeHtml = (value) => {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
};

// Nach Empfänger-Mail gruppieren
const empfMap = new Map();

const addZuordnung = (mail, name, row) => {
  const key = String(mail || '').trim().toLowerCase();
  if (!key) return;

  if (!empfMap.has(key)) {
    empfMap.set(key, {
      Name: name,
      Mail: mail,
      positionen: [],
      seen: new Set(),
    });
  }

  const gruppe = empfMap.get(key);
  // Eindeutigkeit pro Position (Bestellnummer + ArtNr), damit PM==Besteller nicht doppelt zählt
  const posKey = `${row.Bestellnummer}|${row.ArtNr}`;
  if (gruppe.seen.has(posKey)) return;
  gruppe.seen.add(posKey);
  gruppe.positionen.push(row);
};

for (const item of items) {
  const row = item.json;
  // Position dem PM zuordnen
  addZuordnung(row.MailProduktmanager, row.Produktmanager, row);
  // Position dem Besteller zuordnen
  addZuordnung(row.MailBesteller, row.Besteller, row);
}

const result = [];

for (const gruppe of empfMap.values()) {
  if (!gruppe.Mail) continue;

  const sortiert = gruppe.positionen
    .sort((a, b) => Number(b.TageUeberfaellig) - Number(a.TageUeberfaellig));

  const zeilen = sortiert.map(row => `
    <tr>
      <td>${escapeHtml(row.Bestellnummer)}</td>
      <td>${escapeHtml(row.Lieferant)}</td>
      <td>${escapeHtml(row.ArtNr)}</td>
      <td>${escapeHtml(row.Artikel)}</td>
      <td align="right">${escapeHtml(row.MengeOffen)}</td>
      <td>${escapeHtml(row.Lieferdatum)}</td>
      <td align="right">${escapeHtml(row.TageUeberfaellig)}</td>
    </tr>`).join('');

  const mailText = `
<p>Hallo ${escapeHtml(gruppe.Name)},</p>

<p>folgende Artikel, für die du als Produktmanager oder Besteller zuständig bist, wurden nicht zum geplanten Liefertermin angeliefert (Bestellung in Bearbeitung, offene Menge, mindestens 1 Tag überfällig):</p>

<table border="1" cellpadding="6" cellspacing="0" style="border-collapse: collapse; font-family: Arial, sans-serif; font-size: 14px;">
  <thead>
    <tr>
      <th align="left">Bestellnr.</th>
      <th align="left">Lieferant</th>
      <th align="left">ArtNr</th>
      <th align="left">Artikel</th>
      <th align="right">Menge offen</th>
      <th align="left">Lieferdatum</th>
      <th align="right">Tage überfällig</th>
    </tr>
  </thead>
  <tbody>${zeilen}
  </tbody>
</table>
`;

  result.push({
    json: {
      Empfaenger: gruppe.Name,
      sendto: gruppe.Mail,
      titel: `${titel} - deine Artikel`,
      anzahlPositionen: sortiert.length,
      mailText,
    },
  });
}

return result;

